long long get_cycle(long long n) {
    long long len = 1;
    while (n != 1) {
        if (n % 2 != 0) n = 3 * n + 1;
        else n = n / 2;
        len++;
    }
    return len;
}

int main() {
    long long i, j;
    while (scanf("%lld %lld", &i, &j) == 2) {
        long long a = i, b = j;
        if (a > b) {
            long long tmp = a; a = b; b = tmp;
        }
        long long max_len = 0;
        for (long long k = a; k <= b; k++) {
            long long cur = get_cycle(k);
            if (cur > max_len) max_len = cur;
        }
        printf("%lld %lld %lld\n", i, j, max_len);
    }
    return 0;
}

