    long long a, b;
    while (scanf("%lld %lld", &a, &b) == 2 && (a != 0 || b != 0)) {
        int carries = 0;
        int carry = 0;
        while (a > 0 || b > 0) {
            int sum = (a % 10) + (b % 10) + carry;
            if (sum >= 10) {
                carry = 1;
                carries++;
            } else {
                carry = 0;
            }
            a /= 10;
            b /= 10;
        }
        if (carries == 0)
            printf("No carry operation.\n");
        else if (carries == 1)
            printf("1 carry operation.\n");
        else
            printf("%d carry operations.\n", carries);
    }
    return 0;
}

