#include <stdio.h>

const int dr[8] = {-1, -1, -1,  0, 0,  1,  1, 1};
const int dc[8] = {-1,  0,  1, -1, 1, -1,  0, 1};

int main() {
    int n, m;
    int field_num = 1;
    while (scanf("%d %d", &n, &m) == 2 && (n != 0 || m != 0)) {
        if (field_num > 1) printf("\n");
        printf("Field #%d:\n", field_num++);
        char grid[105][105];
        for (int i = 0; i < n; i++) {
            scanf("%s", grid[i]);
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '*') {
                    putchar('*');
                } else {
                    int count = 0;
                    for (int k = 0; k < 8; k++) {
                        int ni = i + dr[k];
                        int nj = j + dc[k];
                        if (ni >= 0 && ni < n && nj >= 0 && nj < m && grid[ni][nj] == '*') {
                            count++;
                        }
                    }
                    putchar('0' + count);
                }
            }
            putchar('\n');
        }
    }
    return 0;
}

